from pathlib import Path
import re

# ---------- Homepage ----------
p = Path('index.html')
html = p.read_text()

# Open Graph / social sharing metadata
needle = '  <meta name="description" content="Productflix by Chirag Kochar — products, experiments, stories and life." />\n'
if 'property="og:title"' not in html:
    og = needle + '''  <meta property="og:title" content="Productflix — Chirag Kochar | Senior Product Manager" />\n  <meta property="og:description" content="Products, AI experiments, product thinking and the work behind Chirag Kochar's product career." />\n  <meta property="og:type" content="website" />\n  <meta property="og:url" content="https://productflix.vercel.app/" />\n  <meta property="og:image" content="https://productflix.vercel.app/assets/photos/navy-blazer.jpg" />\n  <meta property="og:image:alt" content="Chirag Kochar, Senior Product Manager" />\n  <meta name="twitter:card" content="summary_large_image" />\n  <link rel="canonical" href="https://productflix.vercel.app/" />\n'''
    html = html.replace(needle, og)

# Resume CTA in hero
old_actions = '''        <div class="hero-actions">\n          <a class="button button-primary" id="heroPrimary" href="#work"><span class="play">▶</span> View Featured Work</a>\n          <a class="button button-secondary" id="heroSecondary" href="product-journey.html"><span class="info">i</span> My Journey</a>\n        </div>'''
new_actions = '''        <div class="hero-actions">\n          <a class="button button-primary" id="heroPrimary" href="#work"><span class="play">▶</span> View Featured Work</a>\n          <a class="button button-secondary" id="heroSecondary" href="product-journey.html"><span class="info">i</span> My Journey</a>\n          <a class="button button-secondary" id="heroResume" href="resume.html">Résumé</a>\n        </div>'''
html = html.replace(old_actions, new_actions)

# Accessible meaningful headshot
html = html.replace('<div class="hiring-portrait"><img src="assets/photos/navy-blazer.jpg" alt=""></div>', '<div class="hiring-portrait"><img src="assets/photos/navy-blazer.jpg" alt="Chirag Kochar, Senior Product Manager"></div>')

# Assay status consistency
html = html.replace('01 · SHIPPED</small><strong>ASSAY</strong>', '01 · LIVE PROTOTYPE</small><strong>ASSAY</strong>')
html = html.replace('<span class="status status-green">LIVE BUILD</span>', '<span class="status status-green">LIVE PROTOTYPE</span>')

# Strengthen Payments proof on card
html = html.replace('<div class="poster-caption"><strong>Payments & Checkout</strong><span>Modern, reliable payments</span></div>', '<div class="poster-caption"><strong>Payments & Checkout</strong><span>$4.2M incremental bookings · 40%→24% abandonment</span></div>')

# Add payments outcome cards after first scale metric if not already present
metric_anchor = '<button class="metric-card" data-open="accounting-payments"><span class="metric-icon">◎</span><div><strong>$180M+</strong><span>Annual transaction flow · SCALE</span></div></button>'
if '$4.2M' not in html.split('id="metricRow"',1)[1].split('</section>',1)[0]:
    html = html.replace(metric_anchor, metric_anchor + '\n          <button class="metric-card" data-open="payments-checkout"><span class="metric-icon">↗</span><div><strong>$4.2M</strong><span>Incremental bookings · REALIZED</span></div></button>\n          <button class="metric-card" data-open="payments-checkout"><span class="metric-icon">↘</span><div><strong>40%→24%</strong><span>Checkout abandonment · REALIZED</span></div></button>')

# CK Labs: stop duplicating Decision Simulator and remove idea-only filler
lab_pattern = re.compile(r'<div class="lab-grid">.*?</div>\n\s*</section>', re.S)
lab_replacement = '''<div class="lab-grid">\n          <a class="lab-card" href="assay.html"><span>LAB 001</span><strong>Assay</strong><small>LIVE PROTOTYPE</small></a>\n          <a class="lab-card" href="ai-product-copilot.html"><span>LAB 002</span><strong>AI Product Copilot</strong><small>PROTOTYPE</small></a>\n          <a class="lab-card" href="productflix-case-study.html"><span>LAB 003</span><strong>Productflix as a Product</strong><small>SHIPPED</small></a>\n        </div>\n      </section>'''
# only replace the build section occurrence
build_start = html.find('<section class="section shelf-section" id="build" data-shelf="build">')
if build_start != -1:
    tail = html[build_start:]
    m = lab_pattern.search(tail)
    if m:
        tail = tail[:m.start()] + lab_replacement + tail[m.end():]
        html = html[:build_start] + tail

# Beyond Product: remove one redundant fifth tile from the homepage only
html = re.sub(r'\s*<article class="life-card[^>]*data-id="in-front-lens".*?</article>', '', html, count=1, flags=re.S)

# Replace .edu email exposure with LinkedIn + Resume links
html = html.replace('<a href="mailto:ckochar@tepper.cmu.edu">Email me →</a>', '<a href="resume.html">Résumé →</a><a href="https://www.linkedin.com/in/datadriven-chiragkochar/" target="_blank" rel="noreferrer">LinkedIn →</a>')
html = html.replace('<div class="cta-actions"><a href="mailto:ckochar@tepper.cmu.edu" class="button button-primary">Let’s Talk</a><a href="https://www.linkedin.com/in/datadriven-chiragkochar/" class="button button-secondary" target="_blank" rel="noreferrer">LinkedIn</a></div>', '<div class="cta-actions"><a href="resume.html" class="button button-primary">View Résumé</a><a href="https://www.linkedin.com/in/datadriven-chiragkochar/" class="button button-secondary" target="_blank" rel="noreferrer">Connect on LinkedIn</a></div>')

p.write_text(html)

# ---------- App data / quick view ----------
p = Path('app.js')
js = p.read_text()
js = js.replace('metrics: [["Travel", "platform"], ["26K", "users"], ["Checkout", "& payments"]]', 'metrics: [["$4.2M", "incremental bookings"], ["40%→24%", "checkout abandonment"], ["Payments", "& checkout"]]')
js = js.replace('metrics: [["26K", "users"], ["Payments", "platform"], ["Conversion", "focus"]]', 'metrics: [["$4.2M", "incremental bookings · realized"], ["40%→24%", "checkout abandonment · realized"], ["Payments", "& checkout"]]')
js = js.replace('meta: "Personal Build · AI · 0→1"', 'meta: "Personal Build · AI · Live Prototype"')
p.write_text(js)

# ---------- Product journey ----------
p = Path('product-journey.html')
journey = p.read_text()
journey = journey.replace('<div class="chips"><b>Reservations</b><b>Payments</b><b>Checkout</b><b>26K users</b></div>', '<div class="chips"><b>$4.2M incremental bookings</b><b>40%→24% abandonment</b><b>Payments</b><b>Checkout</b></div>')
p.write_text(journey)

# ---------- Publicis / payments episode ----------
p = Path('publicis-reservation.html')
publicis = p.read_text()
publicis = publicis.replace('<div class="meta"><span>Travel & Hospitality</span><span>~26K users</span><span>Reservation + checkout</span><span>Payments</span></div>', '<div class="meta"><span>Travel & Hospitality</span><span>$4.2M incremental bookings</span><span>40%→24% abandonment</span><span>Payments + checkout</span></div>')
publicis = publicis.replace('<div class="metric-grid"><div class="metric"><strong>26K</strong><span>users on the broader platform</span></div><div class="metric"><strong>4</strong><span>connected moments: reserve · checkout · pay · confirm</span></div><div class="metric"><strong>1</strong><span>customer journey that has to feel seamless</span></div></div>', '<div class="metric-grid"><div class="metric"><strong>$4.2M</strong><span>incremental bookings · realized</span></div><div class="metric"><strong>40%→24%</strong><span>checkout abandonment · realized</span></div><div class="metric"><strong>PAYMENTS</strong><span>reliability, conversion and failure recovery</span></div></div>')
p.write_text(publicis)

# ---------- Resume page ----------
resume = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chirag Kochar — Résumé</title><meta name="description" content="Résumé for Chirag Kochar, Senior Product Manager across AI, financial platforms, payments and enterprise workflows."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{--bg:#090b0e;--panel:#11161c;--text:#f5f1e8;--muted:#9aa3ad;--gold:#f2c66d;--line:rgba(255,255,255,.1)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Manrope,Arial,sans-serif}a{color:inherit;text-decoration:none}.nav{height:68px;padding:0 5vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:sticky;top:0;background:rgba(9,11,14,.9);backdrop-filter:blur(14px)}.brand{font-weight:800}.brand span{color:var(--gold)}.actions{display:flex;gap:10px}.button{border:1px solid var(--line);padding:10px 14px;border-radius:10px;font-size:12px;background:#121820}.button.primary{background:var(--gold);color:#17110a;border:0;font-weight:800}.wrap{width:min(980px,90vw);margin:auto}.hero{padding:70px 0 34px}.kicker{color:var(--gold);font-size:11px;font-weight:800;letter-spacing:.12em}.hero h1{font-size:clamp(48px,7vw,82px);line-height:.95;margin:12px 0 14px;letter-spacing:-.05em}.hero p{color:#c6ccd2;font-size:18px;line-height:1.6;max-width:780px}.chips{display:flex;gap:9px;flex-wrap:wrap;margin-top:20px}.chips span{border:1px solid var(--line);border-radius:999px;padding:8px 11px;color:#c2c9d0;font-size:11px}.section{padding:34px 0;border-top:1px solid var(--line)}.section h2{font-size:26px;margin:0 0 20px}.role{display:grid;grid-template-columns:180px 1fr;gap:26px;padding:22px 0;border-top:1px solid rgba(255,255,255,.06)}.role:first-of-type{border-top:0}.role .when{color:var(--muted);font-size:12px}.role h3{margin:0 0 5px;font-size:20px}.role h4{margin:0 0 12px;color:var(--gold);font-size:13px}.role ul{margin:0;padding-left:18px;color:#c1c8ce;line-height:1.65;font-size:14px}.edu{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.edu div{padding:18px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.edu strong{display:block;margin-bottom:6px}.edu span{font-size:12px;color:var(--muted)}@media(max-width:700px){.role{grid-template-columns:1fr}.edu{grid-template-columns:1fr}}@media print{body{background:#fff;color:#111}.nav{display:none}.wrap{width:92%}.section{border-color:#ddd}.role h4,.kicker{color:#7b5b1c}.hero p,.role ul,.role .when,.edu span{color:#444}}</style></head><body><nav class="nav"><a class="brand" href="index.html">PRODUCT<span>FLIX</span></a><div class="actions"><a class="button" href="index.html">Back to portfolio</a><button class="button primary" onclick="window.print()">Print / Save PDF</button></div></nav><main class="wrap"><section class="hero"><div class="kicker">CHIRAG KOCHAR · SENIOR PRODUCT MANAGER</div><h1>AI. PLATFORMS.<br>PAYMENTS.</h1><p>Senior Product Manager with 8.5+ years across enterprise systems, financial infrastructure, payments and AI-assisted workflow automation. I turn high-friction operational problems into measurable product outcomes.</p><div class="chips"><span>$180M+ transaction scale</span><span>AI + document intelligence</span><span>Payments & checkout</span><span>Enterprise platforms</span><span>Plano, TX</span></div></section><section class="section"><h2>Experience</h2><div class="role"><div class="when">2025 — Present</div><div><h3>Senior Product Manager</h3><h4>ServiceLink</h4><ul><li>Lead platform modernization across financial operations, reconciliation, payments and regulated enterprise workflows.</li><li>Delivered realized improvements including 30% lower reconciliation effort and 23% faster vendor payment cycles across high-value transaction flows.</li><li>Lead AI-assisted workflow initiatives spanning document intelligence, configurable automation, exception routing and human review.</li></ul></div></div><div class="role"><div class="when">2022 — 2023</div><div><h3>Product Manager — Payments & Checkout</h3><h4>Publicis Sapient · Travel & Hospitality</h4><ul><li>Improved checkout and payment journeys, reducing abandonment from 40% to 24%.</li><li>Expanded payment capabilities and unlocked $4.2M in incremental bookings.</li><li>Owned transaction reliability, integrations and customer experience across reservation and checkout flows.</li></ul></div></div><div class="role"><div class="when">2016 — 2021</div><div><h3>Associate Consultant / Implementation Manager</h3><h4>Capgemini</h4><ul><li>Delivered digital manufacturing and MES transformation across 50+ plants.</li><li>Worked across plant systems, integrations, rollout coordination and operational change.</li></ul></div></div></section><section class="section"><h2>Additional product experience</h2><div class="role"><div class="when">2024</div><div><h3>Founding PM · LUPR</h3><h4>0→1 supplier intelligence</h4><ul><li>Worked on customer discovery, product strategy, supplier-risk integrations and an AI assistant during graduate school.</li></ul></div></div></section><section class="section"><h2>Education & credentials</h2><div class="edu"><div><strong>Carnegie Mellon University</strong><span>M.S. Product Management · 2024</span></div><div><strong>IIM Udaipur</strong><span>MBA · Global Supply Chain Management</span></div><div><strong>Mechanical Engineering</strong><span>B.E. · Parul University</span></div></div><div class="chips"><span>AWS Certified Cloud Practitioner</span><span>SAFe Product Owner / Product Manager</span><span>Lean Six Sigma Green Belt</span></div></section><section class="section"><div class="actions"><a class="button primary" href="https://www.linkedin.com/in/datadriven-chiragkochar/" target="_blank" rel="noreferrer">LinkedIn</a><a class="button" href="index.html#work">Portfolio work</a></div></section></main></body></html>'''
Path('resume.html').write_text(resume)

# ---------- Productflix meta case study ----------
case = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Productflix as a Product — Chirag Kochar</title><meta name="description" content="How Chirag Kochar treated his portfolio as a product discovery and ranking problem."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="episode.css"></head><body><nav class="episode-nav"><a class="episode-brand" href="index.html">PRODUCT<span>FLIX</span></a><a class="back" href="index.html#build">← Back to Building</a></nav><header class="hero"><div><div class="eyebrow">SHIPPED · PORTFOLIO AS PRODUCT</div><h1>ONE CATALOG.<em>DIFFERENT INTENTS.</em></h1><p>I treated my portfolio as a discovery problem: recruiters, AI product leaders, builders and personal-network visitors arrive with different jobs-to-be-done, but the underlying content is the same.</p><div class="meta"><span>Ranking, not filtering</span><span>?mode= deep links</span><span>Mobile-first switching</span><span>Measure next</span></div></div><div class="hero-visual"><div class="route"></div><div class="ticket a"><small>VISITOR INTENT</small><strong>HIRING</strong></div><div class="ticket b"><small>SAME CATALOG</small><strong>RE-RANKED</strong></div><div class="checkout"><small>PRODUCT PRINCIPLE</small><i></i><i></i><i></i><b>SHOW RELEVANCE FAST</b></div></div></header><section class="section"><div class="section-inner"><div class="kicker">THE PROBLEM</div><h2>A rich portfolio can become a navigation problem.</h2><p class="lead">The site had professional work, AI thinking, prototypes, career history and personal stories. The risk was that a first-time visitor had to understand the information architecture before finding the evidence they cared about.</p></div></section><section class="section"><div class="section-inner"><div class="kicker">THE PRODUCT BET</div><h2>Rank the same catalog by visitor intent.</h2><div class="three"><article class="card"><span>01 · HIRING</span><h3>Evidence first</h3><p>Lead with shipped work, realized outcomes and career context.</p></article><article class="card"><span>02 · PRODUCT × AI</span><h3>Trust & judgment first</h3><p>Prioritize AI products, rules-vs-model decisions and human-in-the-loop thinking.</p></article><article class="card"><span>03 · BUILDING / LIFE</span><h3>Different proof</h3><p>Re-rank toward prototypes or personal stories without creating separate sites.</p></article></div></div></section><section class="section"><div class="section-inner"><div class="kicker">DESIGN PRINCIPLES</div><h2>The important choices were behavioral, not visual.</h2><div class="decision"><div class="quote">“Personalization should reduce discovery cost, not create another gate.”</div><ul><li><b>Ranking, not filtering:</b> content stays discoverable in every mode.</li><li><b>No forced intro:</b> the base URL opens directly in the Hiring cut.</li><li><b>URL beats memory:</b> explicit <code>?mode=</code> deep links always win.</li><li><b>Tap first:</b> mode switching works without hover-only interactions.</li><li><b>Channel-aware:</b> application links can open directly in the most relevant cut.</li></ul></div></div></section><section class="section"><div class="section-inner"><div class="kicker">WHAT I’D MEASURE</div><h2>Personalization is only useful if it changes behavior.</h2><div class="metric-grid"><div class="metric"><strong>CTR</strong><span>featured work clicks by mode</span></div><div class="metric"><strong>RESUME</strong><span>résumé clicks by acquisition path</span></div><div class="metric"><strong>CONTACT</strong><span>LinkedIn / contact conversion by mode</span></div></div></div></section><section class="cta"><h2>The portfolio became part of the portfolio.</h2><p>The point was not to copy Netflix visually. It was to adapt catalog-navigation logic to a different discovery problem.</p><a class="button" href="index.html?mode=building">Back to Building →</a></section></body></html>'''
Path('productflix-case-study.html').write_text(case)

print('Credibility/recruiter polish applied.')
